<script setup lang="ts">
import {computed,onActivated,onDeactivated,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {getInventoryPage,getInventoryGroups,getInventoryMaster,getInventoryGroupMasters,saveInventoryMaster,getInventoryReferences,inventoryLifecycle,type InventoryMaster} from '@/api/modules/foundation'
import {useCachedRequest} from '@/composables/useCachedRequest'
import PageContainer from '@/components/PageContainer/index.vue'
import MasterDataLifecycleDialog from '@/components/MasterDataLifecycleDialog.vue'
import {useUserStore} from '@/stores/user'
import {newRequestId} from '@/api/modules/partner'
import {partnerError} from '@/utils/partnerError'
import type {InventoryListRow,InventoryTreeNode} from '@/types/foundation'
import type {MasterDataLifecycleAction,MasterDataLifecycleInput} from '@/types/masterDataLifecycle'
defineOptions({name:'InventoryCenterView'})
const route=useRoute(),router=useRouter(),user=useUserStore()
const page=ref(1),size=ref(50),keyword=ref(''),itemGroup=ref('all'),timeRange=ref('all')
const canWrite=computed(()=>user.hasPermission('*')||!!user.profile?.canMaintainEngineeringData)
const pageRequest=useCachedRequest(getInventoryPage),groupRequest=useCachedRequest(()=>getInventoryGroups())
const items=ref<InventoryListRow[]>([]),total=ref(0),groups=ref<InventoryTreeNode[]>([]),groupMasters=ref<InventoryMaster[]>([])
const {loading,error}=pageRequest
let active=true,initialized=false,timer:ReturnType<typeof setTimeout>|undefined,detailSeq=0
const detail=ref<InventoryMaster>(),detailGroup=ref(false),detailVisible=ref(false),detailLoading=ref(false),editing=ref(false),busy=ref(false),formError=ref('')
const form=ref<Partial<InventoryMaster>&{requestId:string;reason?:string}>({requestId:''}),groupVisible=ref(false)
const lifeRecord=ref<{id:number,name:string,code:string}>(),lifeGroup=ref(false),lifeAction=ref<MasterDataLifecycleAction>('delete')
const context=computed(()=>JSON.stringify([route.fullPath,user.token,user.permissions]))
const typeLabels:Record<string,string>={material:'原材料',semi_finished:'半成品',finished:'成品',packaging:'包材',tooling:'模具',fixture:'治具'}
const status=(v:string)=>v==='inactive'?'停用':({active:'启用',draft:'草稿',available:'可用',reserved:'已预留',consumed:'已耗用',closed:'已关闭',in_use:'使用中'} as Record<string,string>)[v]||v
const groupOptions=computed(()=>groups.value.flatMap(root=>root.children||[]))
function load(force=false){return pageRequest.execute({page:page.value,size:size.value,keyword:keyword.value.trim(),nodeId:itemGroup.value,timeRange:timeRange.value},force)}
async function refresh(){pageRequest.invalidate();groupRequest.invalidate();await Promise.all([load(true),groupRequest.execute(undefined,true)]);if(groupVisible.value)await loadGroupMasters()}
function search(debounce=false){clearTimeout(timer);page.value=1;pageRequest.invalidate();if(active){if(debounce)timer=setTimeout(()=>void load(),300);else void load()}}
watch(keyword,()=>search(true));watch([itemGroup,timeRange,size],()=>search())
watch(pageRequest.data,v=>{if(v){items.value=v.content;total.value=v.totalElements}});watch(groupRequest.data,v=>{if(v)groups.value=v})
async function loadGroupMasters(){const token=user.token;try{const value=await getInventoryGroupMasters();if(token===user.token)groupMasters.value=value}catch(e){if(token===user.token)ElMessage.error(partnerError(e))}}
async function showGroups(){groupVisible.value=true;await loadGroupMasters()}
async function open(id:number,group=false){const token=user.token,serial=++detailSeq;detailGroup.value=group;detailVisible.value=true;detailLoading.value=true;editing.value=false;formError.value='';detail.value=undefined;try{const value=await getInventoryMaster(id,group);if(serial===detailSeq&&token===user.token)detail.value=value}catch(e){if(serial===detailSeq&&token===user.token)formError.value=partnerError(e)}finally{if(serial===detailSeq&&token===user.token)detailLoading.value=false}}
function create(group=false){++detailSeq;detailGroup.value=group;detail.value=undefined;editing.value=true;detailVisible.value=true;formError.value='';form.value={code:'',name:'',spec:'',unit:'',inventoryType:'material',remark:'',groupId:itemGroup.value.startsWith('material-group:')?Number(itemGroup.value.split(':')[1]):undefined,requestId:newRequestId()}}
function edit(){if(!detail.value)return;form.value={...detail.value,requestId:newRequestId(),reason:''};formError.value='';editing.value=true}
async function closeDetail(){if(busy.value)return;if(editing.value){try{await ElMessageBox.confirm('关闭后放弃本次未保存的内容？','未保存内容')}catch{return}}++detailSeq;detailVisible.value=false;editing.value=false}
async function save(){if(busy.value||!canWrite.value)return;const token=user.token,serial=detailSeq;if(!form.value.code?.trim()||!form.value.name?.trim()||(!detailGroup.value&&!form.value.unit?.trim())){formError.value='请填写编码、名称'+(detailGroup.value?'':'及库存单位');return}busy.value=true;formError.value='';try{const saved=await saveInventoryMaster(detail.value?.id,form.value,detailGroup.value);if(token!==user.token||serial!==detailSeq)return;detail.value=saved;editing.value=false;ElMessage.success('已保存');await refresh()}catch(e){if(token===user.token&&serial===detailSeq)formError.value=partnerError(e)}finally{if(token===user.token&&serial===detailSeq)busy.value=false}}
function lifecycle(row:InventoryMaster|InventoryListRow,action:MasterDataLifecycleAction,group=false){lifeGroup.value=group;lifeAction.value=action;lifeRecord.value={id:'itemId'in row?Number(row.itemId):row.id,name:row.name,code:row.code}}
const inspect=(id:number|string)=>getInventoryReferences(id,lifeGroup.value)
const perform=(id:number|string,action:MasterDataLifecycleAction,payload:MasterDataLifecycleInput)=>inventoryLifecycle(id,action,payload,lifeGroup.value)
async function completed(result:unknown){const token=user.token,serial=detailSeq;lifeRecord.value=undefined;const r=result as InventoryMaster;if(detail.value?.id===r.id&&detailGroup.value===lifeGroup.value){if(r.deleted)detailVisible.value=false;else{try{const updated=await getInventoryMaster(r.id,lifeGroup.value);if(token!==user.token||serial!==detailSeq)return;detail.value=updated}catch(e){if(token===user.token&&serial===detailSeq)formError.value=partnerError(e)}}}if(token===user.token&&serial===detailSeq)await refresh()}
function openReference(path:string){if(path.startsWith('/'))void router.push(path)}
watch(()=>route.query.inventoryId,id=>{if(id)void open(Number(id))},{immediate:true})
watch(()=>user.token,()=>{++detailSeq;clearTimeout(timer);pageRequest.clear();groupRequest.clear();pageRequest.data.value=undefined;groupRequest.data.value=undefined;items.value=[];total.value=0;groups.value=[];groupMasters.value=[];detail.value=undefined;detailVisible.value=false;editing.value=false;busy.value=false;form.value={requestId:''};formError.value='';groupVisible.value=false;lifeRecord.value=undefined},{flush:'sync'})
onMounted(()=>{initialized=true;void groupRequest.execute(undefined);void load()})
onActivated(()=>{active=true;if(initialized){void groupRequest.execute(undefined);void load()}})
onDeactivated(()=>{active=false;clearTimeout(timer);pageRequest.invalidate()});onUnmounted(()=>clearTimeout(timer))
</script>
<template><PageContainer title="物料库存" class="inventory-page"><template #actions><el-button v-if="canWrite" type="primary" @click="create()">新增物料</el-button><el-button @click="showGroups">物料组</el-button><el-button @click="refresh">刷新</el-button></template>
 <div class="inventory-filters"><el-select v-model="itemGroup" placeholder="全部物料组"><el-option label="全部物料" value="all"/><el-option v-for="g in groupOptions" :key="g.nodeId" :label="g.label" :value="g.nodeId"/></el-select><el-select v-model="timeRange"><el-option label="全部时间" value="all"/><el-option label="最近7天" value="7d"/><el-option label="最近30天" value="30d"/><el-option label="最近90天" value="90d"/></el-select><el-input v-model="keyword" clearable placeholder="搜索编码／名称／规格／供应商／产品"/><el-button @click="search()">查询</el-button></div>
 <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="load(true)">重试</el-button></el-alert>
 <div class="inventory-list" v-loading="loading"><div class="inventory-heading"><span>物料／编码</span><span>分类／规格</span><span>产品／型号</span><span>库存／状态</span><span>操作</span></div><el-empty v-if="!items.length&&!loading" description="暂无物料"/><article v-for="row in items" :key="row.itemId" class="inventory-row"><div><el-button link type="primary" @click="open(Number(row.itemId))">{{row.name}}</el-button><p>{{row.code}}</p></div><div>{{row.inventoryType}}<p>{{row.spec}}</p></div><div>{{row.productName||'—'}}<p>{{row.phoneModel||'—'}} · {{row.supplierName}}</p></div><div>{{row.stock}}<p><el-tag size="small" :type="row.status==='inactive'?'info':'success'">{{status(row.status)}}</el-tag></p></div><div class="row-actions"><el-button link @click="open(Number(row.itemId))">详情</el-button><template v-if="canWrite"><el-button link @click="open(Number(row.itemId)).then(edit)">编辑</el-button><el-button link @click="lifecycle(row,row.status==='inactive'?'activate':'deactivate')">{{row.status==='inactive'?'启用':'停用'}}</el-button><el-button link type="danger" @click="lifecycle(row,'delete')">删除</el-button></template></div></article></div>
 <div class="inventory-pagination"><span>共 {{total}} 条</span><el-pagination v-model:page-size="size" v-model:current-page="page" :page-sizes="[20,50,100]" :total="total" :pager-count="5" layout="sizes,prev,pager,next" @current-change="load()"/></div>
 <el-drawer :model-value="detailVisible" :title="(editing?(detail?'编辑':'新增'):'查看')+(detailGroup?'物料组':'物料')" size="min(640px,100vw)" :before-close="closeDetail" :close-on-click-modal="false" class="inventory-detail"><div v-loading="detailLoading"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/>
  <el-form v-if="editing" label-position="top" :disabled="busy"><el-form-item label="编码" required><el-input v-model="form.code" :disabled="!!detail" placeholder="保留原始编码与前导零"/></el-form-item><el-form-item label="名称" required><el-input v-model="form.name" :disabled="!!detail?.sourceNameReadonly"/><span v-if="detail?.sourceNameReadonly" class="field-origin">名称由 {{detail.sourceSystem}} 同步维护</span></el-form-item><template v-if="!detailGroup"><el-form-item label="物料类型" required><el-select v-model="form.inventoryType"><el-option v-if="form.inventoryType&&!typeLabels[form.inventoryType]" :value="form.inventoryType" :label="'历史分类：'+form.inventoryType+'（保留原值）'"/><el-option v-for="(label,key) in typeLabels" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="库存单位" required><el-input v-model="form.unit" placeholder="例如 pcs、kg、set"/></el-form-item><el-form-item label="物料组"><el-select v-model="form.groupId" clearable><el-option v-if="form.groupId&&!groupOptions.some(g=>Number(g.nodeId.split(':')[1])===form.groupId)" :value="form.groupId" label="已停用分组（保留原关联）" disabled/><el-option v-for="g in groupOptions" :key="g.nodeId" :label="g.label" :value="Number(g.nodeId.split(':')[1])"/></el-select></el-form-item><el-form-item label="规格／型号"><el-input v-model="form.spec" type="textarea" autosize/></el-form-item></template><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" autosize/></el-form-item><el-form-item v-if="detail" label="修改原因" required><el-input v-model="form.reason" type="textarea" autosize/></el-form-item></el-form>
  <dl v-else-if="detail" class="inventory-facts"><dt>编码</dt><dd>{{detail.code}}</dd><dt>名称</dt><dd>{{detail.name}}<span v-if="detail.sourceNameReadonly" class="field-origin"> · {{detail.sourceSystem}} 同步</span></dd><dt>状态</dt><dd>{{status(detail.status)}}</dd><template v-if="!detailGroup"><dt>规格／型号</dt><dd>{{detail.spec||'—'}}</dd><dt>库存余额</dt><dd>{{detail.quantity??0}} {{detail.unit}}</dd><dt>库存状态</dt><dd>{{status(detail.stockStatus||'')}}</dd></template><dt>备注</dt><dd>{{detail.remark||'—'}}</dd><dt>更新时间</dt><dd>{{detail.updatedAt}}</dd></dl></div><template #footer><el-button :disabled="busy" @click="closeDetail">关闭</el-button><el-button v-if="editing" type="primary" :loading="busy" @click="save">保存</el-button><template v-else-if="detail&&canWrite"><el-button type="primary" @click="edit">编辑</el-button><el-button @click="lifecycle(detail,detail.status==='inactive'?'activate':'deactivate',detailGroup)">{{detail.status==='inactive'?'启用':'停用'}}</el-button><el-button type="danger" plain @click="lifecycle(detail,'delete',detailGroup)">删除</el-button></template></template></el-drawer>
 <el-dialog v-model="groupVisible" title="物料组" width="min(760px,95vw)" class="inventory-groups"><div class="group-toolbar"><span>{{groupMasters.length}} 个分组</span><el-button v-if="canWrite" type="primary" @click="create(true)">新增物料组</el-button></div><div class="group-list"><article v-for="g in groupMasters" :key="g.id" class="group-row"><div><strong>{{g.name}}</strong><p>{{g.code}} · {{status(g.status)}}</p></div><div class="row-actions"><el-button link @click="open(g.id,true)">详情</el-button><template v-if="canWrite"><el-button link @click="open(g.id,true).then(edit)">编辑</el-button><el-button link @click="lifecycle(g,g.status==='inactive'?'activate':'deactivate',true)">{{g.status==='inactive'?'启用':'停用'}}</el-button><el-button link type="danger" @click="lifecycle(g,'delete',true)">删除</el-button></template></div></article></div></el-dialog>
 <MasterDataLifecycleDialog :record="lifeRecord" :kind-label="lifeGroup?'物料组':'物料'" :action="lifeAction" :editable="canWrite" :context="context" :load="inspect" :perform="perform" @close="lifeRecord=undefined" @completed="completed" @open="openReference"/>
 </PageContainer></template>
<style scoped>
.inventory-page{height:100%;min-height:0;display:flex;flex-direction:column;gap:8px;container-type:inline-size;font-size:12px;line-height:16px;--el-component-size:28px}.inventory-page :deep(.page-panel){padding:6px 12px}.inventory-page :deep(.page-panel-header){margin-bottom:0}.inventory-row :deep(.el-tag){height:16px;line-height:14px;vertical-align:top}.inventory-page :deep(.page-panel-title){font-size:16px}.inventory-page :deep(.el-button){font-size:12px;height:28px;min-height:28px}.inventory-filters{display:flex;gap:8px;flex-wrap:wrap}.inventory-filters>.el-select{width:180px}.inventory-filters>.el-input{flex:1;min-width:180px}.inventory-list{flex:1;min-height:0;overflow:auto;background:#fff;border:1px solid #d9e1ec;border-radius:6px}.inventory-heading,.inventory-row{display:grid;grid-template-columns:1.5fr .85fr 1.1fr .7fr minmax(150px,auto);gap:10px;padding:4px 12px}.inventory-heading{position:sticky;top:0;background:#f0f4fa;color:#43516a;font-weight:700;z-index:1}.inventory-row{border-bottom:1px solid #e6ebf2;align-items:center;min-height:44px;line-height:16px}.inventory-row>div{min-width:0;overflow-wrap:anywhere}.inventory-row p{margin:1px 0 0;color:#64748b;font-size:12px;line-height:16px}.group-row p{margin:4px 0 0;color:#64748b;font-size:12px}.row-actions{display:flex;gap:8px;flex-wrap:wrap}.row-actions .el-button+.el-button{margin-left:0}.inventory-row .el-button{padding:0;border:0;white-space:normal;height:auto;line-height:16px;min-height:16px;text-align:left;max-width:100%}.inventory-pagination,.group-toolbar,.group-row{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}.field-origin{font-size:12px;color:#64748b;margin-top:4px}.inventory-facts{display:flex;flex-direction:column;gap:6px;margin:0}.inventory-facts dt{font-weight:700;color:#334155;margin-top:12px}.inventory-facts dd{margin:0;background:#f5f8fc;border:1px solid #e0e8f0;border-radius:4px;padding:8px;white-space:pre-wrap;overflow-wrap:anywhere}.group-list{max-height:60dvh;overflow:auto}.group-row{padding:10px 0;border-bottom:1px solid #e2e8f0}.inventory-detail :deep(.el-form-item__label){font-size:12px;font-weight:700;color:#334155}.inventory-detail :deep(.el-input__wrapper.is-focus),.inventory-detail :deep(.el-textarea__inner:focus){background:#eff6ff}.inventory-detail :deep(.el-form-item){margin-bottom:16px}.inventory-detail :deep(.el-select){width:100%}
@container(max-width:760px){.inventory-heading{display:none}.inventory-row{grid-template-columns:1fr 1fr}.inventory-row>.row-actions{grid-column:1/-1;border-top:1px solid #edf2f7;padding-top:4px}}
@container(max-width:500px){.inventory-row{grid-template-columns:1fr}.inventory-filters>.el-select{flex:1;min-width:120px}.inventory-pagination :deep(.el-pager){display:none}.inventory-pagination{justify-content:flex-start}}
</style>
